              {copy.items.map((item, i) => {
            const Visual = VISUALS[i % VISUALS.length];
            return (<Article key={item.title} index={i} className={i < copy.items.length - 1 ? "art:flex art:min-w-0 art:flex-col art:border-border art:border-b art:@min-[768px]/artemis:border-r art:@min-[768px]/artemis:border-b-0" : "art:flex art:min-w-0 art:flex-col art:border-border"}>
                <Intro n={String(i + 1)} title={item.title} body={item.description}/>
                <Visual step={step}/>
              </Article>);
        })}
            </div>
          </div>
        </section>
      </div>
    </>);
}
